#include "calib.h"

#include <string.h>

#include "edge_config.h"

/* PLACEHOLDER signatures until E0/E4 capture real ones. Generated by
 * sim/tools/gen_endmembers.py from unit-peak Gaussian channel responses (ams
 * datasheet peaks and FWHMs), a 590/15 nm amber line and a two-hump
 * cool-white LED model. Rerun the script if the model changes. */
static const float k_shape_lamp[EDGE_SPEC_NCH] = {
    0.00000f, 0.00000f, 0.00000f, 0.00000f, 0.00010f, 0.02435f,
    0.40063f, 0.53230f, 0.04251f, 0.00011f, 0.00000f, 0.00000f,
};
static const float k_shape_broad[EDGE_SPEC_NCH] = {
    0.00327f, 0.01719f, 0.15605f, 0.06232f, 0.10513f, 0.12189f,
    0.28679f, 0.18518f, 0.05140f, 0.01003f, 0.00075f, 0.00000f,
};

/* PLACEHOLDER: lux per basic count is unknown until the sensor is on the
 * bench; 1.0 makes amplitudes read as lux until `cal` sets the real value. */
#define LAMP_PHOT_PER_AMP 1.0f

/* Same model: a cool-white unit amplitude carries 0.66x the photopic lux of
 * an amber one (most of its counts fall in the blue channels). */
#define BROAD_OVER_LAMP_PHOT 0.6604f

void edge_calib_defaults(edge_calib_t *c)
{
    memcpy(c->shape[EDGE_EM_LAMP], k_shape_lamp, sizeof k_shape_lamp);
    memcpy(c->shape[EDGE_EM_BROAD], k_shape_broad, sizeof k_shape_broad);
    c->phot_per_amp[EDGE_EM_LAMP]  = LAMP_PHOT_PER_AMP;
    c->phot_per_amp[EDGE_EM_BROAD] = LAMP_PHOT_PER_AMP * BROAD_OVER_LAMP_PHOT;
    c->sp_ratio[EDGE_EM_LAMP]      = EDGE_SP_AMBER;
    c->sp_ratio[EDGE_EM_BROAD]     = EDGE_SP_BROAD;
}

void edge_calib_set_lamp_scale(edge_calib_t *c, float lux_per_amp)
{
    if (!(lux_per_amp > 0.0f)) {
        return;
    }
    const float ratio = lux_per_amp / c->phot_per_amp[EDGE_EM_LAMP];
    c->phot_per_amp[EDGE_EM_LAMP]   = lux_per_amp;
    c->phot_per_amp[EDGE_EM_BROAD] *= ratio;
}
